/* Aktiv content for Deutsch B1: speaking tasks, writing prompts, verbs with prepositions, Redemittel.
   Written for Damian at B1 level. [de, en] pairs are used for anything shown in the app's two interface languages. */

/* ---------- SPRECHEN ----------
   type "dlg": a conversation. The app speaks the partner's line (p), you answer. h = what to do, m = a model answer.
   type "mono": you speak on your own. pts = points to cover, m = model answer, sec = target speaking time. */
const SP_CATS = {
  alltag: ["Alltagsgespräche", "Everyday conversations"],
  leben:  ["Über mein Leben", "About my life"],
  disk:   ["Diskutieren & planen", "Discuss & plan"],
  praes:  ["Kurze Präsentation", "Short presentation"]
};
const SP_PHR = { alltag:["bitten","nachfragen","zeit"], leben:["erzaehlen","meinung","zeit"], disk:["vorschlag","reagieren","zustimmen","widersprechen","einigen"], praes:["praes","vornach","meinung"] };

const SPRECHEN = [
/* ---- Alltag ---- */
{id:"arzt", cat:"alltag", type:"dlg", t:["Beim Arzt anrufen","Calling the doctor"],
 sit:["Du rufst in einer Arztpraxis an. Du hast seit drei Tagen Halsschmerzen und brauchst einen Termin.","You call a doctor's surgery. You've had a sore throat for three days and need an appointment."],
 turns:[
  {p:"Praxis Dr. Weber, guten Tag. Was kann ich für Sie tun?", h:["Sag, wer du bist, und bitte um einen Termin.","Say who you are and ask for an appointment."], m:"Guten Tag, hier spricht Damian. Ich hätte gern einen Termin, am liebsten heute oder morgen."},
  {p:"Was fehlt Ihnen denn?", h:["Beschreib deine Beschwerden: was, seit wann, wie stark.","Describe your symptoms: what, since when, how bad."], m:"Ich habe seit drei Tagen starke Halsschmerzen, und seit gestern habe ich auch Fieber."},
  {p:"Heute ist leider alles voll. Morgen um halb neun wäre noch etwas frei.", h:["Die Zeit passt dir nicht. Frag nach einer anderen Uhrzeit.","That time doesn't suit you. Ask for another time."], m:"Um halb neun kann ich leider nicht, da muss ich arbeiten. Geht es vielleicht auch am Nachmittag?"},
  {p:"Am Nachmittag geht es um 15 Uhr. Waren Sie schon einmal bei uns?", h:["Nimm den Termin an. Sag, dass du zum ersten Mal kommst, und frag, was du mitbringen musst.","Accept. Say it's your first time and ask what to bring."], m:"Ja, 15 Uhr passt gut. Nein, ich komme zum ersten Mal. Was muss ich mitbringen?"},
  {p:"Bringen Sie bitte Ihre Versichertenkarte mit. Dann bis morgen!", h:["Bedank dich und verabschiede dich.","Say thank you and goodbye."], m:"Gut, mache ich. Vielen Dank für Ihre Hilfe. Auf Wiederhören!"}
 ]},
{id:"wohnung", cat:"alltag", type:"dlg", t:["Wohnungsbesichtigung","Viewing a flat"],
 sit:["Du besichtigst eine Wohnung. Der Vermieter zeigt sie dir.","You're viewing a flat. The landlord is showing you round."],
 turns:[
  {p:"Hallo, Sie kommen sicher wegen der Wohnung. Kommen Sie rein! Das hier ist das Wohnzimmer.", h:["Begrüße ihn und sag, was dir gefällt.","Greet him and say what you like."], m:"Guten Tag! Ja, genau. Oh, das Wohnzimmer ist schön hell. Das gefällt mir sehr."},
  {p:"Die Wohnung hat zwei Zimmer, eine Küche und ein Bad. Haben Sie Fragen?", h:["Frag nach der Miete und den Nebenkosten.","Ask about the rent and the extra costs."], m:"Ja, wie hoch ist die Miete? Und sind die Nebenkosten schon dabei?"},
  {p:"Die Kaltmiete ist 750 Euro, dazu kommen etwa 180 Euro Nebenkosten.", h:["Frag, ab wann die Wohnung frei ist und ob Haustiere erlaubt sind.","Ask when it's free and whether pets are allowed."], m:"Ab wann ist die Wohnung frei? Und darf man hier Haustiere haben?"},
  {p:"Sie ist ab dem ersten Dezember frei. Eine Katze wäre kein Problem. Was machen Sie beruflich?", h:["Erzähl kurz von deinem Beruf und warum die Wohnung gut passt.","Briefly say what you do and why the flat suits you."], m:"Ich bin Softwareentwickler und arbeite oft von zu Hause. Deshalb ist ein ruhiges, helles Zimmer für mich sehr wichtig."},
  {p:"Das klingt gut. Möchten Sie die Wohnung nehmen?", h:["Du hast Interesse, möchtest aber noch nachdenken. Frag, bis wann du dich melden musst.","You're interested but want to think. Ask by when you must reply."], m:"Ich habe großes Interesse, aber ich möchte noch kurz darüber nachdenken. Bis wann muss ich mich bei Ihnen melden?"}
 ]},
{id:"baumarkt", cat:"alltag", type:"dlg", t:["Im Baumarkt","At the DIY store"],
 sit:["Du brauchst Material für dein Aquaponik-System. Ein Verkäufer spricht dich an.","You need materials for your aquaponics system. A sales assistant comes over."],
 turns:[
  {p:"Guten Tag, kann ich Ihnen helfen?", h:["Sag, wofür du Material suchst.","Say what you need materials for."], m:"Ja, gern. Ich baue gerade ein kleines Aquaponik-System und suche das passende Material."},
  {p:"Ah, interessant. Was brauchen Sie denn genau?", h:["Nenne zwei Dinge: Rohre und eine Pumpe.","Name two things: pipes and a pump."], m:"Ich brauche ungefähr zehn Meter Rohr und eine kleine Wasserpumpe, die leise und sparsam ist."},
  {p:"Rohre haben wir in 20 und in 32 Millimetern. Welchen Durchmesser brauchen Sie?", h:["Du bist unsicher. Frag, was er empfiehlt.","You're not sure. Ask what he recommends."], m:"Da bin ich mir nicht sicher. Was würden Sie mir empfehlen, wenn das Wasser zu den Pflanzen fließen soll?"},
  {p:"Für Ihr System würde ich 32 Millimeter nehmen. Die Pumpe hier kostet 89 Euro.", h:["Das ist dir zu teuer. Frag nach einer günstigeren Pumpe.","Too expensive. Ask for a cheaper pump."], m:"Das ist mir ein bisschen zu teuer. Haben Sie vielleicht auch eine günstigere Pumpe?"},
  {p:"Ja, diese hier für 59 Euro ist auch gut, nur etwas lauter.", h:["Entscheide dich und frag, ob du sie zurückgeben kannst.","Decide, and ask if you can return it."], m:"Dann nehme ich die günstigere. Kann ich sie zurückgeben, wenn sie nicht funktioniert?"}
 ]},
{id:"amt", cat:"alltag", type:"dlg", t:["Beim Bürgeramt","At the registration office"],
 sit:["Du bist umgezogen und möchtest deine neue Adresse anmelden.","You've moved and want to register your new address."],
 turns:[
  {p:"Guten Morgen. Was ist Ihr Anliegen?", h:["Sag, was du möchtest.","Say what you want."], m:"Guten Morgen. Ich bin vor zwei Wochen umgezogen und möchte meinen neuen Wohnsitz anmelden."},
  {p:"Haben Sie die Wohnungsgeberbestätigung von Ihrem Vermieter dabei?", h:["Du kennst das Wort nicht. Bitte um eine Erklärung.","You don't know the word. Ask what it means."], m:"Entschuldigung, das Wort kenne ich nicht. Können Sie bitte erklären, was eine Wohnungsgeberbestätigung ist?"},
  {p:"Das ist ein Formular. Ihr Vermieter bestätigt damit, dass Sie dort wohnen.", h:["Du hast es nicht dabei. Frag, was du jetzt machen sollst.","You don't have it. Ask what to do now."], m:"Ach so. Das habe ich leider nicht dabei. Was soll ich jetzt machen?"},
  {p:"Sie können es morgen bringen. Ohne das Formular geht es leider nicht.", h:["Frag, ob du dafür einen neuen Termin brauchst.","Ask whether you need a new appointment."], m:"Muss ich dafür einen neuen Termin machen, oder kann ich einfach vorbeikommen?"},
  {p:"Kommen Sie einfach morgen zwischen acht und zwölf Uhr vorbei.", h:["Wiederhole die Zeit, um sicherzugehen, und bedank dich.","Repeat the time to be sure, and say thanks."], m:"Alles klar, also morgen zwischen acht und zwölf. Vielen Dank, auf Wiedersehen!"}
 ]},
{id:"reklamation", cat:"alltag", type:"dlg", t:["Etwas reklamieren","Returning a faulty item"],
 sit:["Dein neuer Wasserkocher ist nach einer Woche kaputt. Du gehst zurück ins Geschäft.","Your new kettle broke after a week. You go back to the shop."],
 turns:[
  {p:"Guten Tag, was kann ich für Sie tun?", h:["Sag, was du gekauft hast und dass es nicht funktioniert.","Say what you bought and that it doesn't work."], m:"Guten Tag. Ich habe letzte Woche diesen Wasserkocher bei Ihnen gekauft, aber er funktioniert nicht mehr."},
  {p:"Oh, das tut mir leid. Was genau ist das Problem?", h:["Beschreib das Problem genau.","Describe the problem exactly."], m:"Er wird nicht mehr heiß. Das Licht geht an, aber das Wasser bleibt kalt."},
  {p:"Haben Sie den Kassenbon dabei?", h:["Ja. Sag, was du möchtest: dein Geld zurück.","Yes. Say what you want: your money back."], m:"Ja, hier ist er. Ich hätte gern mein Geld zurück, bitte."},
  {p:"Wir können das Gerät reparieren lassen oder Ihnen ein neues geben. Geld zurück geht leider nicht.", h:["Reagiere höflich, aber bestimmt, und entscheide dich.","React politely but firmly, and decide."], m:"Hm, das finde ich schade. Eine Reparatur dauert sicher lange. Dann nehme ich lieber ein neues Gerät."},
  {p:"In Ordnung, ich hole Ihnen ein neues aus dem Lager.", h:["Bedank dich und frag nach der Garantie.","Say thanks and ask about the guarantee."], m:"Vielen Dank. Gilt für das neue Gerät auch wieder die volle Garantie?"}
 ]},
{id:"nachbarin", cat:"alltag", type:"dlg", t:["Die neue Nachbarin","The new neighbour"],
 sit:["Im Treppenhaus triffst du zum ersten Mal deine Nachbarin.","You meet your neighbour on the stairs for the first time."],
 turns:[
  {p:"Hallo! Sie sind der neue Nachbar, oder? Ich bin Frau Krüger aus dem dritten Stock.", h:["Stell dich vor und sag, seit wann du hier wohnst.","Introduce yourself and say since when you've lived here."], m:"Hallo, ja genau! Ich heiße Damian und wohne seit Anfang des Monats hier im zweiten Stock."},
  {p:"Willkommen! Der Postbote hat übrigens ein Paket für Sie bei mir abgegeben.", h:["Bedank dich und frag, wann du es abholen kannst.","Thank her and ask when you can collect it."], m:"Oh, wie nett von Ihnen, vielen Dank! Wann kann ich es bei Ihnen abholen?"},
  {p:"Heute Abend ab sechs bin ich zu Hause. Darf ich noch etwas sagen? Die Musik gestern Abend war ziemlich laut.", h:["Entschuldige dich und erkläre kurz, was los war.","Apologise and briefly explain."], m:"Oh, das tut mir wirklich leid. Ich hatte Freunde zu Besuch und habe nicht gemerkt, wie laut es war."},
  {p:"Kein Problem, aber nach zehn Uhr ist hier Ruhezeit.", h:["Versprich, dass es nicht wieder passiert, und lade sie ein.","Promise it won't happen again and invite her."], m:"Das wusste ich nicht. Es kommt nicht wieder vor. Darf ich Sie als Entschuldigung mal auf einen Kaffee einladen?"},
  {p:"Gern, das ist sehr freundlich!", h:["Schlag einen Tag vor.","Suggest a day."], m:"Wie wäre es am Samstagnachmittag? Dann können wir uns ein bisschen kennenlernen."}
 ]},
{id:"restaurant", cat:"alltag", type:"dlg", t:["Tisch reservieren (Telefon)","Booking a table (phone)"],
 sit:["Du rufst in einem Restaurant an und möchtest für Samstag reservieren.","You call a restaurant to book for Saturday."],
 turns:[
  {p:"Restaurant Seeblick, guten Abend.", h:["Sag, was du möchtest: wann, wie viele Personen.","Say what you want: when, how many people."], m:"Guten Abend. Ich möchte gern einen Tisch für vier Personen reservieren, für Samstagabend um acht Uhr."},
  {p:"Um acht ist leider schon alles voll. Um halb acht oder um neun hätte ich noch etwas.", h:["Wähle eine Zeit.","Choose a time."], m:"Dann nehmen wir halb acht, das ist kein Problem."},
  {p:"Gut. Möchten Sie drinnen sitzen oder auf der Terrasse?", h:["Sag, was du möchtest, und begründe es.","Say what you'd like and why."], m:"Lieber auf der Terrasse, weil man von dort den See sieht. Falls es regnet, dann gern drinnen."},
  {p:"Notiert. Auf welchen Namen darf ich reservieren?", h:["Nenne deinen Namen und frag nach vegetarischen Gerichten.","Give your name and ask about vegetarian dishes."], m:"Auf den Namen Damian, bitte. Eine Frage noch: Haben Sie auch vegetarische Gerichte? Eine Freundin isst kein Fleisch."},
  {p:"Ja, wir haben mehrere vegetarische Gerichte auf der Karte.", h:["Bedank dich und verabschiede dich.","Say thanks and goodbye."], m:"Super, vielen Dank. Dann bis Samstag. Auf Wiederhören!"}
 ]},
{id:"bank", cat:"alltag", type:"dlg", t:["Bei der Bank","At the bank"],
 sit:["Du möchtest in Deutschland ein Konto eröffnen.","You want to open a bank account in Germany."],
 turns:[
  {p:"Guten Tag, wie kann ich Ihnen helfen?", h:["Sag, was du möchtest.","Say what you want."], m:"Guten Tag. Ich möchte gern ein Girokonto bei Ihnen eröffnen."},
  {p:"Gern. Wohnen Sie schon in Deutschland?", h:["Erkläre: Du lebst teils in Barbados, teils in Deutschland.","Explain: you live partly in Barbados, partly in Germany."], m:"Ich lebe einen Teil des Jahres in Deutschland und den anderen Teil in Barbados. Meine Adresse hier ist angemeldet."},
  {p:"Verstehe. Wofür brauchen Sie das Konto hauptsächlich?", h:["Nenne zwei Gründe.","Give two reasons."], m:"Hauptsächlich für die Miete und meine Rechnungen. Außerdem bekomme ich Zahlungen von Kunden aus Europa."},
  {p:"Unser Konto kostet fünf Euro im Monat. Online-Banking ist inklusive.", h:["Frag nach einem kostenlosen Konto und nach Überweisungen ins Ausland.","Ask about a free account and transfers abroad."], m:"Gibt es auch ein kostenloses Konto? Und was kostet eine Überweisung ins Ausland?"},
  {p:"Überweisungen in Euro sind kostenlos, andere Währungen kosten extra. Ein kostenloses Konto gibt es nur für Studenten.", h:["Sag, dass du es dir überlegst, und bitte um Unterlagen.","Say you'll think about it and ask for the documents."], m:"Danke für die Informationen. Ich überlege es mir noch. Können Sie mir die Unterlagen mitgeben?"}
 ]},

/* ---- Über mein Leben ---- */
{id:"vorstellen", cat:"leben", type:"mono", sec:90, t:["Stell dich vor","Introduce yourself"],
 sit:["Stell dich ausführlich vor, wie bei einem neuen Kurs oder einem neuen Team.","Introduce yourself in detail, as in a new class or team."],
 pts:[["Name, Herkunft, Wohnort","Name, origin, where you live"],["Beruf","Job"],["Freizeit","Free time"],["Warum Deutsch?","Why German?"],["Pläne","Plans"]],
 m:"Ich heiße Damian und komme aus Barbados. Ich lebe einen Teil des Jahres in Barbados und den anderen Teil in Deutschland. Von Beruf bin ich Softwareentwickler, und außerdem habe ich eine kleine Aquaponik-Farm. In meiner Freizeit baue ich gern Dinge, und ich bin oft draußen auf der Farm. Ich lerne Deutsch, weil ich mich in Deutschland ohne Hilfe verständigen möchte. Die A1-Prüfung habe ich schon bestanden, und jetzt lerne ich für B1. Mein Ziel ist, in einem Jahr fließend mit Kunden und Nachbarn zu sprechen."},
{id:"farm", cat:"leben", type:"mono", sec:120, t:["Meine Farm erklären","Explaining my farm"],
 sit:["Jemand fragt dich: „Was ist eigentlich Aquaponik?“ Erkläre es.","Someone asks you: “What actually is aquaponics?” Explain."],
 pts:[["Was ist Aquaponik?","What is aquaponics?"],["Wie funktioniert dein System?","How does your system work?"],["Was baust du an?","What do you grow?"],["Was ist schwierig?","What's difficult?"],["Warum ist es wichtig?","Why does it matter?"]],
 m:"Auf meiner Farm in Barbados mache ich Aquaponik. Das ist eine Kombination aus Fischzucht und Pflanzenanbau. Das Wasser aus dem Fischbecken fließt zu den Pflanzen. Bakterien verwandeln die Abfälle der Fische in Nährstoffe, und die Pflanzen reinigen dabei das Wasser. Danach bringt eine Pumpe das saubere Wasser zurück zu den Fischen. So geht fast kein Wasser verloren. Ich baue vor allem Salat, Kräuter und Tomaten an. Schwierig ist manchmal der pH-Wert, den ich jeden Tag messen muss. Ich finde dieses System wichtig, weil man damit auch auf kleinen Flächen nachhaltig Lebensmittel produzieren kann."},
{id:"beruf", cat:"leben", type:"mono", sec:120, t:["Mein Beruf","My job"],
 sit:["Erzähl, was du beruflich machst.","Talk about your work."],
 pts:[["Was machst du?","What do you do?"],["Ein aktuelles Projekt","A current project"],["Ein normaler Arbeitstag","A normal working day"],["Was gefällt dir, was nicht?","What do you like and dislike?"]],
 m:"Ich bin Full-Stack-Entwickler und arbeite selbstständig. Das heißt, ich programmiere sowohl die Benutzeroberfläche als auch den Server und die Datenbank. Im Moment entwickle ich kleine Anwendungen für Firmen in Barbados, zum Beispiel eine App, mit der Geschäfte ihre Quittungen speichern können. Normalerweise fange ich früh am Morgen an, weil ich dann am besten nachdenken kann. Zuerst lese ich meine E-Mails, dann programmiere ich und teste neue Funktionen. An meinem Beruf gefällt mir, dass ich Probleme lösen kann und flexibel bin. Weniger gut gefällt mir, dass ich oft zu lange vor dem Bildschirm sitze."},
{id:"bbde", cat:"leben", type:"mono", sec:120, t:["Barbados und Deutschland","Barbados and Germany"],
 sit:["Vergleiche dein Leben in Barbados und in Deutschland.","Compare your life in Barbados and in Germany."],
 pts:[["Wetter und Natur","Weather and nature"],["Essen","Food"],["Menschen und Alltag","People and daily life"],["Was vermisst du?","What do you miss?"]],
 m:"Barbados und Deutschland sind sehr unterschiedlich. In Barbados ist es das ganze Jahr warm, und man ist fast immer draußen. In Deutschland gibt es vier Jahreszeiten, und im Winter ist es oft kalt und dunkel. Auch das Essen ist anders: In Barbados isst man viel Fisch, Reis und scharfe Soßen, in Deutschland eher Brot, Kartoffeln und Wurst. Die Menschen in Barbados sind meistens sehr locker und spontan. In Deutschland ist vieles besser organisiert, und Pünktlichkeit ist sehr wichtig. Wenn ich in Deutschland bin, vermisse ich das Meer. Wenn ich in Barbados bin, vermisse ich das gute Brot."},
{id:"tag", cat:"leben", type:"mono", sec:90, t:["Ein typischer Tag","A typical day"],
 sit:["Beschreib einen normalen Tag in deinem Leben.","Describe a normal day in your life."],
 pts:[["Morgen","Morning"],["Arbeit","Work"],["Mittag und Nachmittag","Midday and afternoon"],["Abend","Evening"],["Wochenende","Weekend"]],
 m:"Mein Tag beginnt meistens um sechs Uhr. Zuerst gehe ich zur Farm, füttere die Fische und kontrolliere die Wasserwerte. Danach frühstücke ich und trinke einen Kaffee. Am Vormittag arbeite ich am Computer, weil ich mich da am besten konzentrieren kann. Mittags mache ich eine längere Pause und koche etwas. Am Nachmittag habe ich oft Besprechungen mit Kunden, oder ich repariere etwas auf der Farm. Abends lerne ich ungefähr eine halbe Stunde Deutsch. Am Wochenende schlafe ich länger und treffe mich mit Freunden."},
{id:"erlebnis", cat:"leben", type:"mono", sec:120, t:["Ein Erlebnis erzählen","Telling a story"],
 sit:["Erzähl von einem Erlebnis, das du nicht vergessen wirst. Benutze die Vergangenheit.","Tell about something you'll never forget. Use the past tense."],
 pts:[["Wann und wo?","When and where?"],["Was ist passiert?","What happened?"],["Wie hast du dich gefühlt?","How did you feel?"],["Was hast du gelernt?","What did you learn?"]],
 m:"Letztes Jahr hatte ich ein Problem auf meiner Farm, das ich nie vergessen werde. Es war mitten in der Nacht, als plötzlich der Strom ausgefallen ist. Die Pumpe hat nicht mehr funktioniert, und die Fische hatten zu wenig Sauerstoff. Ich bin sofort aufgestanden und habe eine Batterie an die Luftpumpe angeschlossen. Ich war sehr nervös, weil ich nicht wusste, ob es reicht. Zum Glück haben fast alle Fische überlebt. Seitdem habe ich immer Notstrom. Ich habe gelernt, dass man für jedes System einen Plan B braucht."},
{id:"zukunft", cat:"leben", type:"mono", sec:90, t:["Meine Pläne","My plans"],
 sit:["Erzähl von deinen Plänen für die Zukunft.","Talk about your plans for the future."],
 pts:[["Nächstes Jahr","Next year"],["Beruflich","Work"],["Mit Deutsch","With German"],["Ein großer Traum","A big dream"]],
 m:"Nächstes Jahr möchte ich meine Farm vergrößern und ein zweites Gewächshaus bauen. Beruflich plane ich, meine Apps in Barbados bekannter zu machen, damit mehr kleine Firmen sie benutzen. Außerdem will ich ein Buch über Technik und Permakultur schreiben. Mit meinem Deutsch werde ich weiter jeden Tag üben. Ich hoffe, dass ich bald ohne Probleme mit Ämtern und Handwerkern telefonieren kann. Mein großer Traum ist, eines Tages auch in Deutschland eine Aquaponik-Farm aufzubauen. Ob das klappt, weiß ich noch nicht, aber ich arbeite daran."},
{id:"warumdeutsch", cat:"leben", type:"mono", sec:90, t:["Warum ich Deutsch lerne","Why I'm learning German"],
 sit:["Erzähl, wie und warum du Deutsch lernst.","Talk about how and why you're learning German."],
 pts:[["Seit wann?","Since when?"],["Warum?","Why?"],["Was ist leicht, was schwer?","What's easy, what's hard?"],["Wie lernst du?","How do you learn?"]],
 m:"Ich lerne seit diesem Jahr Deutsch. Ich habe angefangen, weil ich regelmäßig in Deutschland bin und mich dort selbst verständigen möchte. Außerdem finde ich es schön, wenn man die Menschen in ihrer eigenen Sprache versteht. Die Aussprache finde ich ziemlich leicht. Schwer sind für mich die Artikel und die Wortstellung, besonders wenn das Verb am Ende stehen muss. Ich lerne jeden Tag mit meinen eigenen Apps: Ich wiederhole Wörter, schreibe kurze Texte und lasse sie korrigieren. Am meisten hilft mir aber, wenn ich wirklich mit Menschen spreche."},

/* ---- Diskutieren & planen ---- */
{id:"feier", cat:"disk", type:"dlg", t:["Eine Abschiedsfeier planen","Planning a leaving party"],
 sit:["Eure Kollegin Anna verlässt die Firma. Du planst mit deinem Kollegen Jonas eine kleine Feier.","Your colleague Anna is leaving the company. You plan a small party with your colleague Jonas."],
 turns:[
  {p:"Hast du gehört? Anna hört Ende des Monats bei uns auf. Wollen wir eine kleine Abschiedsfeier organisieren?", h:["Stimm zu und schlag einen Termin vor.","Agree and suggest a date."], m:"Ja, das habe ich gehört. Gute Idee! Wie wäre es mit ihrem letzten Arbeitstag, also Freitag, dem 28.?"},
  {p:"Freitag ist gut. Aber wo? Ich dachte an ein Restaurant in der Stadt.", h:["Mach einen anderen Vorschlag und begründe ihn.","Make a different suggestion and give a reason."], m:"Ein Restaurant ist schön, aber ziemlich teuer für alle. Was hältst du davon, wenn wir hier im Büro feiern? Dann können auch alle kommen."},
  {p:"Hm, im Büro ist es nicht so gemütlich. Und wer kümmert sich um das Essen?", h:["Gib ihm teilweise recht und mach einen Vorschlag zum Essen.","Partly agree and suggest something for the food."], m:"Da hast du recht. Wir könnten das Büro ein bisschen dekorieren. Und beim Essen schlage ich vor, dass jeder etwas mitbringt."},
  {p:"Okay, das gefällt mir. Und ein Geschenk? Jeder gibt fünf Euro?", h:["Stimm zu und übernimm eine Aufgabe.","Agree and take on a task."], m:"Ja, fünf Euro sind in Ordnung. Ich kann das Geld einsammeln und das Geschenk kaufen. Kannst du die Einladung an alle schicken?"},
  {p:"Klar, mache ich. Also: Freitag, im Büro, jeder bringt etwas mit, und du kaufst das Geschenk.", h:["Bestätige und sag, wie es weitergeht.","Confirm and say what happens next."], m:"Genau, so machen wir es. Ich schreibe dir morgen, wie viel Geld zusammengekommen ist."}
 ]},
{id:"ausflug", cat:"disk", type:"dlg", t:["Einen Ausflug planen","Planning a day trip"],
 sit:["Du planst mit einem Freund einen Ausflug am Wochenende.","You plan a weekend trip with a friend."],
 turns:[
  {p:"Wir haben am Wochenende endlich mal frei. Sollen wir zusammen einen Ausflug machen?", h:["Sag ja und frag, wohin.","Say yes and ask where to."], m:"Ja, sehr gern! Hast du schon eine Idee, wohin wir fahren könnten?"},
  {p:"Ich würde gern in die Berge fahren und wandern.", h:["Nenne einen Nachteil und mach einen anderen Vorschlag.","Name a drawback and suggest something else."], m:"Wandern klingt gut, aber die Fahrt in die Berge dauert ziemlich lange. Wir könnten stattdessen an den See fahren, das ist näher."},
  {p:"Am See ist am Wochenende aber immer sehr viel los.", h:["Gib ihm recht und finde eine Lösung.","Agree and find a solution."], m:"Stimmt, da hast du recht. Dann lass uns früh losfahren, so gegen acht Uhr. Dann ist es noch ruhig."},
  {p:"Okay. Fahren wir mit dem Auto oder mit dem Zug?", h:["Sag deine Meinung und begründe sie.","Give your opinion and a reason."], m:"Ich finde, wir sollten mit dem Zug fahren. Das ist entspannter, und wir müssen keinen Parkplatz suchen."},
  {p:"Einverstanden. Was nehmen wir mit?", h:["Teile die Aufgaben auf.","Split the tasks."], m:"Ich mache Sandwiches, und du bringst Getränke und eine Decke mit. Die Zugtickets kaufe ich heute Abend online."}
 ]},
{id:"homeoffice", cat:"disk", type:"dlg", t:["Homeoffice oder Büro?","Working from home or the office?"],
 sit:["Ein Bekannter findet, dass alle wieder im Büro arbeiten sollten. Diskutiert.","An acquaintance thinks everyone should go back to the office. Discuss."],
 turns:[
  {p:"Viele Firmen holen ihre Mitarbeiter jetzt wieder ins Büro. Ich finde das richtig. Was meinst du?", h:["Widersprich höflich und sag deine Meinung.","Disagree politely and give your view."], m:"Da bin ich anderer Meinung. Ich arbeite selbst meistens von zu Hause und bin dort viel produktiver."},
  {p:"Aber im Büro kann man sich doch viel besser austauschen.", h:["Gib ihm teilweise recht und nenne einen Vorteil vom Homeoffice.","Partly agree and name an advantage of home working."], m:"Das stimmt teilweise. Aber im Homeoffice spart man jeden Tag Zeit, weil man nicht pendeln muss."},
  {p:"Und was ist mit der Einsamkeit? Viele fühlen sich zu Hause allein.", h:["Stimm zu und mach einen Vorschlag.","Agree and make a suggestion."], m:"Das ist ein wichtiger Punkt. Deshalb finde ich eine Mischung am besten, zum Beispiel zwei Tage im Büro und drei Tage zu Hause."},
  {p:"Hm, aber nicht jeder hat zu Hause einen ruhigen Arbeitsplatz.", h:["Nenne eine mögliche Lösung.","Suggest a possible solution."], m:"Da hast du recht. Die Firmen könnten dann Geld für einen Schreibtisch oder einen Platz in einem Coworking-Space geben."},
  {p:"Okay, eine Mischung klingt vernünftig. Würdest du selbst gern in einem Büro arbeiten?", h:["Antworte ehrlich und begründe.","Answer honestly with a reason."], m:"Ab und zu schon, weil ich dann mehr Kontakt zu anderen Menschen hätte. Aber jeden Tag möchte ich das nicht."}
 ]},
{id:"regional", cat:"disk", type:"dlg", t:["Regional einkaufen?","Buying local?"],
 sit:["Eine Freundin kauft nur im Supermarkt. Ihr diskutiert über regionale Lebensmittel.","A friend only shops at the supermarket. You discuss local food."],
 turns:[
  {p:"Ich kaufe Obst und Gemüse nur noch im Supermarkt, weil es dort billiger ist. Findest du das schlecht?", h:["Sag deine Meinung zu regionalen Lebensmitteln.","Give your view on local food."], m:"Schlecht nicht, aber ich kaufe lieber regional, zum Beispiel auf dem Markt. Dann weiß ich, woher die Lebensmittel kommen."},
  {p:"Aber regionale Produkte sind oft viel teurer.", h:["Gib das zu und nenne einen Vorteil.","Admit it and name an advantage."], m:"Das stimmt, sie kosten oft etwas mehr. Dafür sind sie frischer, und die Transportwege sind kürzer. Das ist besser für die Umwelt."},
  {p:"Im Winter gibt es hier aber kaum regionales Gemüse.", h:["Erzähl von deiner Erfahrung mit dem Anbau.","Tell her about your growing experience."], m:"Das ist ein Problem, ja. Aber in Gewächshäusern oder mit Aquaponik kann man auch im Winter Gemüse anbauen. Das mache ich auf meiner Farm."},
  {p:"Interessant! Glaubst du, dass das in Zukunft normal wird?", h:["Sag, was du vermutest, und begründe es.","Say what you expect and why."], m:"Ich glaube schon, weil immer mehr Menschen in Städten leben und es weniger Platz gibt. Solche Systeme brauchen wenig Fläche und wenig Wasser."},
  {p:"Vielleicht sollte ich doch öfter auf den Markt gehen.", h:["Reagiere positiv und gib einen Tipp.","React positively and give a tip."], m:"Probier es einfach mal aus! Am besten gehst du am Samstagmorgen, dann ist die Auswahl am größten."}
 ]},
{id:"kinderhandy", cat:"disk", type:"dlg", t:["Ein Smartphone für Kinder?","A smartphone for children?"],
 sit:["Eine Bekannte erzählt von ihrer Nichte, die ein Smartphone möchte. Diskutiert.","An acquaintance tells you her niece wants a smartphone. Discuss."],
 turns:[
  {p:"Meine Nichte ist neun und möchte unbedingt ein Smartphone. Ihre Eltern sind dagegen. Wie siehst du das?", h:["Sag deine Meinung.","Give your opinion."], m:"Ich finde, mit neun Jahren ist das noch zu früh. Ein einfaches Handy zum Telefonieren reicht in dem Alter."},
  {p:"Aber alle ihre Freundinnen haben schon eins. Sie fühlt sich ausgeschlossen.", h:["Zeig Verständnis, aber bleib bei deiner Meinung.","Show understanding but keep your view."], m:"Das kann ich gut verstehen. Trotzdem sind die Gefahren im Internet für Kinder ziemlich groß."},
  {p:"Man kann doch Regeln machen, zum Beispiel nur eine Stunde am Tag.", h:["Stimm dem Vorschlag teilweise zu.","Partly agree with the suggestion."], m:"Das ist eine gute Idee. Mit klaren Regeln und einer Kindersicherung wäre es für mich in Ordnung."},
  {p:"Und ab wann findest du ein eigenes Smartphone okay?", h:["Nenne ein Alter und begründe es.","Name an age and give a reason."], m:"Ich würde sagen, ab zwölf. Dann wechseln die Kinder meistens auf eine neue Schule und brauchen das Handy auch für die Organisation."},
  {p:"Ich glaube, ich rede mal mit ihren Eltern.", h:["Unterstütze die Idee und fasse zusammen.","Support the idea and sum up."], m:"Gute Idee. Vielleicht findet ihr zusammen einen Kompromiss: ein einfaches Handy jetzt und ein Smartphone später."}
 ]},
{id:"geschenk", cat:"disk", type:"dlg", t:["Ein Geschenk aussuchen","Choosing a present"],
 sit:["Ihr möchtet eurem Freund Tom zusammen etwas zum Geburtstag schenken.","You want to give your friend Tom a birthday present together."],
 turns:[
  {p:"Nächste Woche hat Tom Geburtstag. Wollen wir ihm zusammen etwas schenken?", h:["Stimm zu und frag nach dem Budget.","Agree and ask about the budget."], m:"Ja, gern! Wie viel wollen wir ungefähr ausgeben?"},
  {p:"So um die 50 Euro. Ich dachte an einen Gutschein.", h:["Du findest einen Gutschein langweilig. Mach einen Vorschlag.","You find a voucher boring. Suggest something."], m:"Ein Gutschein ist ein bisschen langweilig, finde ich. Tom kocht doch so gern. Wie wäre es mit einem Kochkurs?"},
  {p:"Ein Kochkurs kostet aber bestimmt mehr als 50 Euro.", h:["Schlag vor, dass noch jemand mitmacht.","Suggest someone else joins in."], m:"Das kann sein. Wir könnten noch Lisa fragen, ob sie mitmacht. Dann teilen wir die Kosten durch drei."},
  {p:"Gute Idee. Und wenn ihm der Termin nicht passt?", h:["Finde eine Lösung.","Find a solution."], m:"Wir kaufen am besten einen Gutschein für einen Kochkurs. Dann kann er den Termin selbst aussuchen."},
  {p:"Perfekt, dann ist es also doch ein Gutschein!", h:["Lach darüber und verteile die Aufgaben.","Laugh about it and split the tasks."], m:"Ja, genau, aber ein besonderer! Ich frage Lisa heute noch, und du suchst einen guten Kochkurs."}
 ]},

/* ---- Präsentation ---- */
{id:"online", cat:"praes", type:"mono", sec:150, t:["Online einkaufen","Shopping online"],
 sit:["Halte eine kurze Präsentation (ca. 2 Minuten) zum Thema „Online einkaufen“.","Give a short presentation (about 2 minutes) on “Shopping online”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Ich möchte euch heute etwas zum Thema „Online einkaufen“ erzählen. Zuerst spreche ich über meine eigenen Erfahrungen, dann über die Situation in Barbados. Danach nenne ich Vor- und Nachteile, und am Ende sage ich meine Meinung. Ich selbst kaufe vor allem Technik und Ersatzteile für meine Farm online, weil es diese Dinge in Barbados oft nicht gibt. In Barbados ist Online-Shopping nicht so einfach wie in Deutschland, denn die Lieferung dauert lange und ist teuer. Ein großer Vorteil ist, dass man rund um die Uhr bestellen und Preise vergleichen kann. Ein Nachteil ist, dass die kleinen Geschäfte in der Stadt weniger Kunden haben. Außerdem gibt es viel Verpackungsmüll. Meiner Meinung nach ist Online-Shopping praktisch, aber man sollte trotzdem die Geschäfte vor Ort unterstützen. Vielen Dank fürs Zuhören! Habt ihr Fragen?"},
{id:"stadtland", cat:"praes", type:"mono", sec:150, t:["Stadt oder Land?","City or countryside?"],
 sit:["Halte eine kurze Präsentation zum Thema „Leben auf dem Land oder in der Stadt“.","Give a short presentation on “Living in the countryside or the city”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Mein Thema heute ist „Leben auf dem Land oder in der Stadt“. Ich erzähle zuerst von mir, dann von der Situation in meinem Heimatland, und danach vergleiche ich die Vor- und Nachteile. Ich wohne in Barbados ziemlich ländlich, in der Nähe meiner Farm. In Deutschland bin ich dagegen oft in der Stadt. In Barbados ziehen viele junge Menschen in die Hauptstadt Bridgetown, weil es dort mehr Arbeit gibt. Auf dem Land ist die Luft besser, es ist ruhiger, und die Mieten sind niedriger. Allerdings braucht man fast immer ein Auto, und es gibt weniger Ärzte und Geschäfte. In der Stadt sind die Wege kurz, und es gibt viele Freizeitangebote, aber es ist laut und teuer. Ich persönlich lebe lieber auf dem Land, weil ich die Natur brauche. Danke für eure Aufmerksamkeit!"},
{id:"sport", cat:"praes", type:"mono", sec:150, t:["Sport im Alltag","Sport in everyday life"],
 sit:["Halte eine kurze Präsentation zum Thema „Sport im Alltag“.","Give a short presentation on “Sport in everyday life”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Ich spreche heute über das Thema „Sport im Alltag“. Zuerst erzähle ich, wie ich selbst Sport mache. Dann berichte ich über Barbados, und am Ende nenne ich Vor- und Nachteile. Ich laufe dreimal pro Woche am Strand, meistens früh am Morgen, bevor es zu heiß wird. Außerdem ist die Arbeit auf der Farm für mich auch eine Art Training. In Barbados sind Cricket und Schwimmen sehr beliebt, und viele Leute treffen sich zum Sport am Strand. Sport ist gut für die Gesundheit und hilft gegen Stress. Man lernt auch neue Leute kennen. Ein Nachteil kann sein, dass man sich verletzt, wenn man zu viel trainiert. Außerdem sind Fitnessstudios oft teuer. Ich finde, man muss nicht viel Geld ausgeben, um fit zu bleiben. Wichtig ist nur, dass man regelmäßig etwas macht. Vielen Dank!"},
{id:"nachhaltig", cat:"praes", type:"mono", sec:150, t:["Nachhaltig leben","Living sustainably"],
 sit:["Halte eine kurze Präsentation zum Thema „Nachhaltig leben“.","Give a short presentation on “Living sustainably”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Heute präsentiere ich das Thema „Nachhaltig leben“. Ich beginne mit meinen eigenen Erfahrungen, spreche dann über Barbados und zum Schluss über Vor- und Nachteile. Auf meiner Farm versuche ich, möglichst wenig Wasser und keine Chemie zu benutzen. Zu Hause trenne ich den Müll und kaufe wenig Plastik. In Barbados ist Umweltschutz ein wichtiges Thema, weil die Insel klein ist und der Müll schnell im Meer landet. Seit einigen Jahren sind zum Beispiel viele Plastikprodukte verboten. Der Vorteil eines nachhaltigen Lebens ist klar: Wir schützen die Natur für die nächsten Generationen. Der Nachteil ist, dass nachhaltige Produkte oft teurer sind und man mehr planen muss. Meiner Meinung nach kann jeder mit kleinen Schritten anfangen. Vielen Dank fürs Zuhören!"},
{id:"ausland", cat:"praes", type:"mono", sec:150, t:["Im Ausland arbeiten","Working abroad"],
 sit:["Halte eine kurze Präsentation zum Thema „Ein Jahr im Ausland arbeiten“.","Give a short presentation on “Working abroad for a year”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Mein Thema ist „Ein Jahr im Ausland arbeiten“. Ich erzähle zuerst von meiner Erfahrung, dann von meinem Heimatland, und danach spreche ich über Vor- und Nachteile. Ich verbringe jedes Jahr mehrere Monate in Deutschland und arbeite von hier aus für meine Kunden. Am Anfang war das nicht leicht, weil ich die Sprache kaum konnte. In Barbados gehen viele junge Leute ins Ausland, vor allem nach Großbritannien, Kanada oder in die USA. Im Ausland lernt man eine neue Sprache und eine andere Kultur kennen. Man wird selbstständiger und offener. Andererseits vermisst man oft die Familie und Freunde, und die Bürokratie kann sehr anstrengend sein. Ich finde, jeder sollte einmal im Leben im Ausland leben, wenn es möglich ist. Danke schön!"},
{id:"ki", cat:"praes", type:"mono", sec:150, t:["KI im Alltag","AI in everyday life"],
 sit:["Halte eine kurze Präsentation zum Thema „Künstliche Intelligenz im Alltag“.","Give a short presentation on “Artificial intelligence in everyday life”."],
 pts:[["Thema vorstellen","Introduce the topic"],["Deine Erfahrung","Your experience"],["Situation in Barbados","The situation in Barbados"],["Vor- und Nachteile, deine Meinung","Pros, cons and your opinion"],["Abschluss und Dank","Close and thank"]],
 m:"Ich möchte heute über „Künstliche Intelligenz im Alltag“ sprechen. Zuerst erzähle ich, wie ich KI benutze, dann spreche ich über die Situation in Barbados, und am Ende sage ich meine Meinung. Ich benutze KI fast jeden Tag, zum Beispiel beim Programmieren und beim Deutschlernen. Sie korrigiert meine Texte und erklärt mir die Grammatik. In Barbados benutzen vor allem junge Leute und Firmen KI, aber viele Menschen sind noch skeptisch. Ein Vorteil ist, dass KI viel Zeit spart und Wissen für alle zugänglich macht. Ein Nachteil ist, dass man nicht immer weiß, ob die Antworten richtig sind. Manche Menschen haben auch Angst, dass sie ihre Arbeit verlieren. Ich denke, KI ist ein nützliches Werkzeug, aber man sollte selbst weiter nachdenken. Vielen Dank für eure Aufmerksamkeit!"}
];

