const SW_CATS = {
  inf:  ["E-Mails an Freunde","Emails to friends"],
  mein: ["Meinung schreiben","Giving your opinion"],
  form: ["Formelle E-Mails","Formal emails"],
  pers: ["Über mich erzählen","Writing about me"]
};
const SW_PHR = { inf:["mail_inf","gefuehl","vorschlag"], mein:["meinung","vornach"], form:["mail_form","bitten","beschwerde"], pers:["erzaehlen","gefuehl"] };
const SCHREIBEN = [
{id:"absage", cat:"inf", w:80, t:["Eine Einladung absagen","Turning down an invitation"],
 task:["Dein Freund Markus hat dich zu seiner Grillparty am Samstag eingeladen. Du kannst nicht kommen. Schreib ihm.","Your friend Markus has invited you to his barbecue on Saturday. You can't go. Write to him."],
 pts:[["Bedank dich für die Einladung.","Thank him for the invitation."],["Erkläre, warum du nicht kommen kannst.","Explain why you can't come."],["Schlag ein anderes Treffen vor.","Suggest meeting another time."]],
 m:"Lieber Markus,\nvielen Dank für deine Einladung zur Grillparty! Ich habe mich sehr darüber gefreut. Leider kann ich am Samstag nicht kommen, weil ich an diesem Wochenende in Hamburg bin. Ein Kunde hat mich zu einem wichtigen Treffen eingeladen, und das kann ich nicht verschieben. Das ist wirklich schade, denn deine Partys sind immer toll.\nHast du vielleicht nächste Woche Zeit? Wir könnten zusammen essen gehen, ich lade dich ein! Sag mir einfach, welcher Tag dir passt.\nIch wünsche euch viel Spaß am Samstag!\nViele Grüße\nDamian"},
{id:"urlaub", cat:"inf", w:80, t:["Vom Urlaub erzählen","Telling a friend about a holiday"],
 task:["Du warst eine Woche im Urlaub. Schreib deiner Freundin Lisa.","You've been on holiday for a week. Write to your friend Lisa."],
 pts:[["Wo warst du und mit wem?","Where were you and who with?"],["Was hast du gemacht?","What did you do?"],["Was hat dir gefallen, was nicht?","What did you like and not like?"]],
 m:"Liebe Lisa,\nwie geht es dir? Ich bin gestern aus dem Urlaub zurückgekommen. Ich war eine Woche mit zwei Freunden an der Ostsee. Wir haben in einem kleinen Hotel direkt am Strand gewohnt.\nJeden Tag sind wir viel Fahrrad gefahren und am Meer spazieren gegangen. Einmal haben wir sogar eine Bootstour gemacht. Am besten haben mir die frischen Fischbrötchen am Hafen gefallen! Nicht so schön war das Wetter, denn es hat fast jeden Tag geregnet, und das Wasser war sehr kalt.\nUnd du? Hast du schon Pläne für den Sommer?\nLiebe Grüße\nDamian"},
{id:"umzug", cat:"inf", w:80, t:["Um Hilfe bitten","Asking for help"],
 task:["Du ziehst nächsten Monat um. Bitte deinen Freund Tom um Hilfe.","You're moving next month. Ask your friend Tom for help."],
 pts:[["Erzähl vom Umzug: wann und wohin?","Tell him about the move: when and where?"],["Bitte um Hilfe: wobei genau?","Ask for help: with what exactly?"],["Biete etwas als Dank an.","Offer something as thanks."]],
 m:"Hallo Tom,\nich habe tolle Neuigkeiten: Ich habe endlich eine neue Wohnung gefunden! Sie ist größer und hat sogar einen kleinen Garten. Am 15. März ziehe ich um.\nLeider habe ich ein Problem: Ich habe kein Auto und viele schwere Möbel. Könntest du mir vielleicht beim Umzug helfen? Es wäre super, wenn du am Samstag ab neun Uhr Zeit hättest. Wir brauchen ungefähr vier Stunden.\nAls Dankeschön koche ich danach für dich, und natürlich gibt es genug zu trinken!\nSag mir bitte bis Freitag Bescheid.\nViele Grüße\nDamian"},
{id:"glueckwunsch", cat:"inf", w:80, t:["Gratulieren","Congratulating a friend"],
 task:["Deine Freundin Sara hat eine neue Stelle bekommen. Schreib ihr.","Your friend Sara has got a new job. Write to her."],
 pts:[["Gratuliere ihr.","Congratulate her."],["Frag nach Details zur neuen Arbeit.","Ask about the new job."],["Schlag vor, zusammen zu feiern.","Suggest celebrating together."]],
 m:"Liebe Sara,\nherzlichen Glückwunsch zu deiner neuen Stelle! Ich freue mich riesig für dich. Du hast so lange gesucht, und jetzt hat es endlich geklappt.\nErzähl mal: Was genau wirst du dort machen? Wie sind die Kollegen, und wann fängst du an? Musst du für die Arbeit eigentlich umziehen, oder kannst du in Köln bleiben?\nDas müssen wir unbedingt feiern! Wie wäre es nächstes Wochenende mit einem Abendessen in unserem Lieblingsrestaurant? Ich lade dich ein.\nIch drücke dir die Daumen für den ersten Arbeitstag!\nLiebe Grüße\nDamian"},
{id:"m_homeoffice", cat:"mein", w:80, t:["Homeoffice oder Büro?","Home or office?"],
 task:["In einem Online-Forum wird gefragt: „Ist Homeoffice besser als das Büro?“ Schreib deine Meinung.","An online forum asks: “Is working from home better than the office?” Write your opinion."],
 pts:[["Deine Meinung","Your opinion"],["Ein Grund mit Beispiel","A reason with an example"],["Ein Gegenargument","A counter-argument"]],
 m:"Ich arbeite seit vielen Jahren im Homeoffice und finde es meistens besser als das Büro. Der wichtigste Grund ist für mich die Zeit: Ich muss nicht pendeln und kann meinen Tag selbst planen. Zum Beispiel arbeite ich früh am Morgen, weil ich mich dann am besten konzentrieren kann, und mache mittags eine lange Pause.\nAllerdings hat das Homeoffice auch Nachteile. Man sieht die Kollegen selten, und manchmal fühlt man sich allein. Deshalb finde ich eine Mischung ideal: ein oder zwei Tage im Büro und den Rest zu Hause."},
{id:"m_social", cat:"mein", w:80, t:["Soziale Medien","Social media"],
 task:["Im Forum: „Machen soziale Medien uns einsamer?“ Schreib deine Meinung.","Forum question: “Does social media make us lonelier?” Write your opinion."],
 pts:[["Deine Meinung","Your opinion"],["Deine eigene Erfahrung","Your own experience"],["Ein Tipp für andere","A tip for others"]],
 m:"Meiner Meinung nach können soziale Medien einsam machen, aber sie müssen es nicht. Ich benutze sie vor allem für meine Arbeit und um Kontakt mit Freunden in anderen Ländern zu halten. Das ist für mich sehr wertvoll, weil ich zwischen Barbados und Deutschland lebe.\nProblematisch wird es, wenn man stundenlang scrollt und sich mit anderen vergleicht. Dann fühlt man sich schnell schlecht. Mein Tipp ist deshalb: Legt das Handy abends weg und trefft eure Freunde lieber persönlich."},
{id:"m_fleisch", cat:"mein", w:80, t:["Weniger Fleisch essen?","Eating less meat?"],
 task:["Im Forum: „Sollten wir alle weniger Fleisch essen?“ Schreib deine Meinung.","Forum question: “Should we all eat less meat?” Write your opinion."],
 pts:[["Deine Meinung","Your opinion"],["Gründe","Reasons"],["Was machst du selbst?","What do you do yourself?"]],
 m:"Ich bin der Meinung, dass die meisten Menschen weniger Fleisch essen sollten. Für die Produktion von Fleisch braucht man sehr viel Wasser und Fläche, und das ist schlecht für die Umwelt. Außerdem ist zu viel rotes Fleisch nicht gesund.\nTrotzdem finde ich, dass niemand ganz auf Fleisch verzichten muss. Ich selbst esse fast nur noch Fisch und Gemüse von meiner eigenen Farm und nur selten Fleisch. Wenn ich Fleisch kaufe, dann lieber weniger, aber dafür gute Qualität von einem Bauern aus der Region."},
{id:"m_apps", cat:"mein", w:80, t:["Sprachen lernen mit Apps","Learning languages with apps"],
 task:["Im Forum: „Kann man mit Apps eine Sprache lernen?“ Schreib deine Meinung.","Forum question: “Can you learn a language with apps?” Write your opinion."],
 pts:[["Deine Meinung","Your opinion"],["Deine Erfahrung","Your experience"],["Was ist außerdem wichtig?","What else matters?"]],
 m:"Ich denke, Apps sind eine große Hilfe, aber allein reichen sie nicht. Ich lerne selbst jeden Tag mit Apps Deutsch. Besonders für Vokabeln sind sie super, weil sie die Wörter genau dann wiederholen, wenn man sie fast vergessen hat.\nSprechen lernt man aber nicht mit einer App. Dafür muss man mit echten Menschen reden, auch wenn man Fehler macht. Deshalb finde ich eine Kombination am besten: Apps für Wörter und Grammatik und Gespräche für die Praxis."},
{id:"f_kurs", cat:"form", w:80, t:["Anfrage an eine Sprachschule","Enquiry to a language school"],
 task:["Du möchtest einen B1-Kurs an einer Sprachschule machen. Schreib eine E-Mail.","You want to take a B1 course at a language school. Write an email."],
 pts:[["Stell dich kurz vor.","Briefly introduce yourself."],["Frag nach Terminen und Preisen.","Ask about dates and prices."],["Frag, ob es einen Einstufungstest gibt.","Ask whether there's a placement test."]],
 m:"Sehr geehrte Damen und Herren,\nich interessiere mich für einen Deutschkurs auf dem Niveau B1 an Ihrer Sprachschule. Ich habe vor Kurzem die A1-Prüfung bestanden und lerne seitdem selbstständig weiter.\nKönnten Sie mir bitte mitteilen, wann der nächste Kurs beginnt und wie viel er kostet? Ich arbeite tagsüber, deshalb wäre ein Abendkurs für mich ideal. Außerdem möchte ich gern wissen, ob ich vorher einen Einstufungstest machen muss.\nIch würde mich über eine baldige Antwort freuen.\nMit freundlichen Grüßen\nDamian"},
{id:"f_hotel", cat:"form", w:80, t:["Beschwerde an ein Hotel","Complaint to a hotel"],
 task:["Du warst in einem Hotel und warst nicht zufrieden. Schreib eine Beschwerde.","You stayed at a hotel and weren't happy. Write a complaint."],
 pts:[["Wann warst du dort?","When were you there?"],["Was war das Problem?","What was the problem?"],["Was erwartest du jetzt?","What do you expect now?"]],
 m:"Sehr geehrte Damen und Herren,\nvom 3. bis 7. Mai habe ich in Ihrem Hotel ein Doppelzimmer mit Meerblick gebucht. Leider war ich mit meinem Aufenthalt gar nicht zufrieden.\nDas Zimmer lag nicht zum Meer, sondern zur Straße, und es war deshalb sehr laut. Außerdem hat die Heizung nicht funktioniert. Ich habe mich zweimal an der Rezeption beschwert, aber niemand hat mir geholfen.\nFür ein Zimmer mit Meerblick habe ich deutlich mehr bezahlt. Ich erwarte deshalb, dass Sie mir einen Teil des Preises zurückerstatten.\nMit freundlichen Grüßen\nDamian"},
{id:"f_absage", cat:"form", w:50, t:["Einen Termin absagen","Cancelling an appointment"],
 task:["Morgen soll ein Handwerker deine Heizung reparieren. Du kannst nicht. Schreib deiner Vermieterin, Frau Schmidt.","A tradesman is due to fix your heating tomorrow. You can't make it. Write to your landlady, Ms Schmidt."],
 pts:[["Entschuldige dich.","Apologise."],["Nenne den Grund.","Give the reason."],["Schlag einen neuen Termin vor.","Suggest a new appointment."]],
 m:"Sehr geehrte Frau Schmidt,\nleider muss ich unseren Termin morgen um 10 Uhr absagen. Ich muss kurzfristig für einen Kunden nach München fahren. Das tut mir sehr leid.\nWäre es möglich, dass der Handwerker am Donnerstag oder Freitag kommt? An beiden Tagen bin ich den ganzen Tag zu Hause.\nMit freundlichen Grüßen\nDamian"},
{id:"f_pumpe", cat:"form", w:80, t:["Anfrage an eine Firma","Enquiry to a company"],
 task:["Du möchtest bei einer deutschen Firma Pumpen für deine Farm bestellen. Schreib eine Anfrage.","You want to order pumps for your farm from a German company. Write an enquiry."],
 pts:[["Was brauchst du?","What do you need?"],["Frag nach Preis und Lieferung nach Barbados.","Ask about price and delivery to Barbados."],["Frag nach der Garantie.","Ask about the guarantee."]],
 m:"Sehr geehrte Damen und Herren,\nauf Ihrer Webseite habe ich gesehen, dass Sie Wasserpumpen für Aquaponik-Anlagen anbieten. Ich betreibe eine kleine Farm in Barbados und brauche drei Pumpen des Modells AP-200.\nKönnten Sie mir bitte ein Angebot schicken? Mich interessiert besonders, ob Sie auch in die Karibik liefern und wie lange die Lieferung ungefähr dauert. Außerdem würde ich gern wissen, wie lange die Garantie gilt.\nVielen Dank im Voraus.\nMit freundlichen Grüßen\nDamian"},
{id:"p_wochenende", cat:"pers", w:80, t:["Mein Wochenende","My weekend"],
 task:["Schreib über dein letztes Wochenende. Benutze das Perfekt.","Write about your last weekend. Use the Perfekt."],
 pts:[["Was hast du gemacht?","What did you do?"],["Mit wem?","Who with?"],["Was war das Beste?","What was the best part?"]],
 m:"Am Wochenende habe ich endlich einmal nicht gearbeitet. Am Samstagmorgen bin ich lange im Bett geblieben und habe gemütlich gefrühstückt. Danach habe ich mit einem Freund ein neues Beet für Kräuter gebaut. Das hat länger gedauert als geplant, weil wir zuerst die richtigen Schrauben nicht gefunden haben. Am Abend haben wir zusammen gegrillt. Am Sonntag bin ich am Strand gelaufen und habe am Nachmittag ein bisschen Deutsch gelernt. Das Beste war aber der Samstagabend, weil wir so viel gelacht haben."},
{id:"p_problem", cat:"pers", w:80, t:["Ein Problem gelöst","A problem I solved"],
 task:["Erzähl von einem Problem, das du gelöst hast.","Write about a problem you solved."],
 pts:[["Was war das Problem?","What was the problem?"],["Was hast du gemacht?","What did you do?"],["Wie ist es ausgegangen?","How did it turn out?"]],
 m:"Letzte Woche hatte ich ein Problem mit einer App, die ich für einen Kunden programmiert habe. Plötzlich konnten die Nutzer ihre Daten nicht mehr speichern. Der Kunde war natürlich sehr nervös. Zuerst habe ich die Fehlermeldungen auf dem Server gelesen, aber ich habe nichts gefunden. Dann habe ich bemerkt, dass die Datenbank voll war. Ich habe alte Daten gelöscht und ein kleines Skript geschrieben, das jede Nacht aufräumt. Seitdem funktioniert alles wieder. Ich habe daraus gelernt, dass man ein System regelmäßig kontrollieren muss."},
{id:"p_ort", cat:"pers", w:70, t:["Ein Ort, den ich liebe","A place I love"],
 task:["Beschreib einen Ort, der dir viel bedeutet.","Describe a place that means a lot to you."],
 pts:[["Wo ist der Ort?","Where is it?"],["Wie sieht er aus?","What does it look like?"],["Warum ist er wichtig für dich?","Why does it matter to you?"]],
 m:"Mein Lieblingsort ist ein kleiner Strand an der Ostküste von Barbados. Dort ist das Meer ziemlich wild, deshalb kann man nicht gut schwimmen. Dafür gibt es große Felsen, hohe Wellen und fast keine Touristen. Wenn ich dort bin, sitze ich meistens auf einem Felsen und höre den Wellen zu. Für mich ist dieser Ort wichtig, weil ich dort am besten nachdenken kann. Viele Ideen für neue Projekte hatte ich genau an diesem Strand."}
];

